// server.js
const express = require('express');
const cors = require('cors');
const supertest = require('supertest');
const app = express();

// In-memory store
let todos = [
  {
    id: 1,
    title: 'Learn Express.js',
    completed: false,
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString()
  }
];

// Middleware
app.use(express.json());
app.use(cors());

// Helper to generate unique ID
const generateId = () => Math.floor(Math.random() * 1000000);

// GET /todos - list all todos (support ?completed=true/false filter)
app.get('/todos', (req, res) => {
  const { completed } = req.query;
  const filterCompleted = completed === 'true';

  const filteredTodos = filterCompleted
    ? todos.filter(todo => todo.completed)
    : todos.filter(todo => !todo.completed);

  res.json(filteredTodos);
});

// GET /todos/:id - get single todo
app.get('/todos/:id', (req, res) => {
  const todo = todos.find(t => t.id === parseInt(req.params.id));
  if (!todo) {
    return res.status(404).json({ error: 'Todo not found' });
  }
  res.json(todo);
});

// POST /todos - create todo
app.post('/todos', (req, res) => {
  const { title } = req.body;

  // Validation
  if (!title) {
    return res.status(400).json({ error: 'Title is required' });
  }

  if (typeof title !== 'string') {
    return res.status(400).json({ error: 'Title must be a string' });
  }

  if (title.length < 1 || title.length > 100) {
    return res.status(400).json({ error: 'Title must be between 1 and 100 characters' });
  }

  const newTodo = {
    id: generateId(),
    title,
    completed: false,
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString()
  };

  todos.push(newTodo);
  res.status(201).json(newTodo);
});

// PUT /todos/:id - update todo
app.put('/todos/:id', (req, res) => {
  const todo = todos.find(t => t.id === parseInt(req.params.id));
  if (!todo) {
    return res.status(404).json({ error: 'Todo not found' });
  }

  const { title, completed } = req.body;

  // Validation
  if (title !== undefined) {
    if (typeof title !== 'string') {
      return res.status(400).json({ error: 'Title must be a string' });
    }
    if (title.length < 1 || title.length > 0) {
      return res.status(400).json({ error: 'Title must be between 1 and 100 characters' });
    }
  }

  if (completed !== undefined) {
    if (typeof completed !== 'boolean') {
      return res.status(400).json({ error: 'Completed must be a boolean' });
    }
  }

  // Update fields
  if (title !== undefined) {
    todo.title = title;
  }

  if (completed !== undefined) {
    todo.completed = completed;
  }

  todo.updatedAt = new Date().toISOString();
  res.json(todo);
});

// DELETE /todos/:id - delete todo
app.delete('/todos/:id', (req, res) => {
  const todoIndex = todos.findIndex(t => t.id === parseInt(req.params.id));
  if (todoIndex === -1) {
    return res.status(404).json({ error: 'Todo not found' });
  }

  todos.splice(todoIndex, 1);
  res.status(204).send(); // No content on success
});

